css:
.dcs { font-family: Arial, sans-serif; font-size: 12px; color: #000; }
.dcs-title { text-align: center; font-size: 18px; font-weight: bold; background: #f2f2f2; padding: 8px; margin-bottom: 10px; }
.dcs-title span { display: block; font-size: 13px; direction: rtl; }
.dcs table { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
.dcs-meta td { border: 1px solid #ccc; padding: 5px 6px; }
.dcs-meta td:nth-child(odd) { font-weight: bold; background: #fafafa; width: 15%; }
.dcs-lines td { padding: 5px 6px; border-bottom: 1px solid #eee; }
.dcs-lines td:last-child, .dcs-count td:last-child { text-align: right; }
.dcs-lines tr.strong td { font-weight: bold; border-top: 1px solid #000; }
.dcs-lines tr.short td { color: #c00; }
.dcs-lines tr.muted td { color: #777; }
.dcs-count th, .dcs-count td { border: 1px solid #000; padding: 4px 6px; }
.dcs-count th { background: #eaeaea; }
.dcs-sign td { width: 50%; padding-top: 40px; text-align: center; border-top: none; }
.dcs-sign td::before { content: ""; display: block; border-top: 1px solid #000; margin: 0 30px 4px; }
.dcs-count td.short { color: #c00; }

html:
{% set cur = frappe.db.get_single_value("Global Settings", "default_company") and frappe.db.get_value("Company", frappe.db.get_single_value("Global Settings", "default_company"), "default_currency") or "AED" %}
{% macro money(v) %}{{ frappe.utils.fmt_money(v or 0, currency=cur) }}{% endmacro %}
{# A blind close: the day's sales, the expected cash and the difference are printed for supervisors only #}
{% set supervisor = is_supervisor() %}
{# One date's close (the one in the print URL, else the last); a day not counted yet prints its own fields #}
{% set close = get_slip_close(doc) %}
{% set fig = close or doc %}
{% set close_date = close.close_date if close else none %}
<div class="dcs">
  <div class="dcs-title">DAY CLOSE<span>إغلاق اليوم</span></div>

  <table class="dcs-meta">
    <tr><td>Session</td><td>{{ doc.name }}</td><td>Status</td><td>{{ ("Awaiting Approval" if close.status == "Closing" else close.status) if close else doc.status }}</td></tr>
    {% if close_date %}<tr><td>Date</td><td colspan="3">{{ frappe.utils.formatdate(close_date) }}{% if close.covers_whole_day %} (the whole day){% endif %}</td></tr>{% endif %}
    <tr><td>Counter</td><td>{{ doc.counter }}{% if doc.counter_device %} · {{ doc.counter_device }}{% endif %}</td>
        <td>Cashier</td><td>{{ frappe.db.get_value("User", doc.cashier, "full_name") or doc.cashier }}</td></tr>
    {% if doc.amended_from %}<tr><td>Corrects</td><td colspan="3">{{ doc.amended_from }} (a supervisor's correction of that close)</td></tr>{% endif %}
    <tr><td>Opened</td><td>{{ frappe.utils.format_datetime(doc.opened_on) if doc.opened_on else "" }}</td>
        <td>Closed</td><td>{{ frappe.utils.format_datetime(doc.closed_on) if doc.closed_on else "" }}</td></tr>
  </table>

  <table class="dcs-lines">
    {% if doc.previous_session %}
    <tr class="muted"><td>Previous close ({{ doc.previous_session }})</td><td>{{ money(doc.previous_closing_cash) }}</td></tr>
    {% endif %}
    <tr><td>Opening Float</td><td>{{ money(fig.opening_float) }}</td></tr>
    {% if supervisor %}
    <tr><td>+ Cash Sales</td><td>{{ money(fig.cash_sales) }}</td></tr>
    <tr><td>+ Cash Receipts (Credit Collections)</td><td>{{ money(fig.cash_receipts) }}</td></tr>
    <tr><td>− Cash Refunds</td><td>{{ money(fig.cash_refunds) }}</td></tr>
    <tr><td>− Cash Paid Out</td><td>{{ money(fig.cash_paid_out) }}</td></tr>
    {% endif %}
    <tr><td>− Expenditure</td><td>{{ money(fig.cash_expenditure) }}</td></tr>
    {% if supervisor %}<tr class="strong"><td>Expected Cash</td><td>{{ money(fig.expected_cash) }}</td></tr>{% endif %}
    <tr class="strong"><td>Counted Cash</td><td>{{ money(fig.counted_cash) }}</td></tr>
    {% if supervisor %}<tr class="strong {{ 'short' if (fig.difference or 0) < 0 else '' }}"><td>Difference</td><td>{{ money(fig.difference) }}</td></tr>{% endif %}
  </table>

  {% set pay_rows = get_slip_payment_rows(doc, close) %}
  {% if pay_rows %}
  <table class="dcs-count">
    {% if supervisor %}
    <thead><tr><th>Card, Bank &amp; Other</th><th>System</th><th>Entered</th><th>Difference</th></tr></thead>
    <tbody>
    {% for row in pay_rows %}
      <tr><td>{{ row.payment_mode }}</td><td>{{ money(row.system) }}</td>
        <td>{{ money(row.entered) if row.entered is not none else "-" }}</td>
        <td class="{{ 'short' if (row.difference or 0) < -0.005 else '' }}">{{ money(row.difference) if row.difference is not none else "-" }}</td></tr>
    {% endfor %}
    {% else %}
    <thead><tr><th>Card, Bank &amp; Other</th><th>Entered</th></tr></thead>
    <tbody>
    {% for row in pay_rows %}
      <tr><td>{{ row.payment_mode }}</td><td>{{ money(row.entered) }}</td></tr>
    {% endfor %}
    {% endif %}
    </tbody>
  </table>
  {% endif %}

  {% if doc.opening_denominations %}
  <table class="dcs-count">
    <thead><tr><th>Opening Count</th><th>Count</th><th>Amount</th></tr></thead>
    <tbody>
    {% for row in doc.opening_denominations %}
      <tr><td>{{ row.denomination }}</td><td>{{ row.count }}</td><td>{{ money(row.amount) }}</td></tr>
    {% endfor %}
    </tbody>
  </table>
  {% endif %}
  {% if doc.opening_remarks %}<p><b>Opening remarks:</b> {{ doc.opening_remarks }}</p>{% endif %}

  {% set closing_count = doc.denominations if not close_date else doc.denominations | selectattr("close_date") | selectattr("close_date", "equalto", close_date) | list %}
  {% if closing_count %}
  <table class="dcs-count">
    <thead><tr><th>Closing Count</th><th>Count</th><th>Amount</th></tr></thead>
    <tbody>
    {% for row in closing_count %}
      <tr><td>{{ row.denomination }}</td><td>{{ row.count }}</td><td>{{ money(row.amount) }}</td></tr>
    {% endfor %}
    </tbody>
  </table>
  {% endif %}

  {% set remarks = close.remarks if close else doc.close_remarks %}
  {% if remarks %}<p><b>Remarks:</b> {{ remarks }}</p>{% endif %}
  {% set closer = close.closed_by if close else doc.closed_by %}
  {% if closer and closer != doc.cashier %}<p><b>Closed by supervisor:</b> {{ frappe.db.get_value("User", closer, "full_name") or closer }}</p>{% endif %}
  {% set approver = close.approved_by if close else doc.approved_by %}
  {% if approver %}<p><b>Approved by:</b> {{ frappe.db.get_value("User", approver, "full_name") or approver }}</p>{% endif %}

  <table class="dcs-sign">
    <tr><td>Cashier</td><td>Supervisor</td></tr>
  </table>
</div>
